1671	    const std::string &column, const IndexParams::Ptr &index_params,
1672	    int concurrency, SegmentMeta::Ptr *segment_meta,
1673	    std::unordered_map<std::string, VectorColumnIndexer::Ptr> *vector_indexers,
1674	    std::unordered_map<std::string, VectorColumnIndexer::Ptr>
1675	        *quant_vector_indexers) {
1676	  auto field = collection_schema_->get_vector_field(column);
1677	  SegmentMeta::Ptr new_segment_meta;
1678	  if (*segment_meta == nullptr) {
1679	    new_segment_meta = std::make_shared<SegmentMeta>(*segment_meta_);
1680	    new_segment_meta->remove_writing_forward_block();
1681	  } else {
1682	    new_segment_meta = *segment_meta;
1683	  }
1684	
1685	  if (segment_meta_->vector_indexed(column) &&
1686	      *field->index_params() == *index_params) {
1687	    // if segment is already indexed and index params are same, skip create
1688	    *segment_meta = new_segment_meta;
1689	    return Status::OK();
1690	  }
1691	  new_segment_meta->add_indexed_vector_field(column);
1692	
1693	  auto vector_index_params =
1694	      std::dynamic_pointer_cast<VectorIndexParams>(index_params);
1695	
1696	  if (vector_index_params->quantize_type() == QuantizeType::UNDEFINED) {
1697	    auto block_id = allocate_block_id();
1698	
1699	    auto field_with_new_index_params = std::make_shared<FieldSchema>(*field);
1700	    field_with_new_index_params->set_index_params(index_params);
1701	
1702	    std::string index_file_path = FileHelper::MakeVectorIndexPath(
1703	        path_, column, segment_meta_->id(), block_id);
1704	    if (FileHelper::FileExists(index_file_path)) {
1705	      LOG_WARN(
1706	          "Index file[%s] already exists (possible crash residue); cleaning "
1707	          "and overwriting.",
1708	          index_file_path.c_str());
1709	      FileHelper::RemoveFile(index_file_path);
1710	    }
1711	    auto vector_indexer = merge_vector_indexer(
1712	        index_file_path, column, *field_with_new_index_params, concurrency);
1713	    if (!vector_indexer.has_value()) {
1714	      return vector_indexer.error();
1715	    }
1716	
1717	    vector_indexers->insert({column, vector_indexer.value()});
1718	
1719	    new_segment_meta->remove_vector_persisted_block(column);
1720	    BlockMeta block;
1721	    block.set_id(block_id);
1722	    block.set_type(BlockType::VECTOR_INDEX);
1723	    block.set_columns({column});
1724	    block.set_min_doc_id(doc_ids_.front());
1725	    block.set_max_doc_id(doc_ids_.back());
1726	    block.set_doc_count(doc_ids_.size());
1727	    new_segment_meta->add_persisted_block(block);
1728	
1729	    *segment_meta = new_segment_meta;
1730	
1731	  } else {
1732	    auto original_index_params =
1733	        std::dynamic_pointer_cast<VectorIndexParams>(field->index_params());
1734	
1735	    core::IndexProvider::Pointer raw_vector_provider;
1736	
1737	    if (!(vector_index_params->metric_type() ==
1738	              original_index_params->metric_type() &&
1739	          vector_indexers_[column].size() == 1)) {
1740	      BlockID block_id = allocate_block_id();
1741	
1742	      auto field_with_flat = std::make_shared<FieldSchema>(*field);
1743	      field_with_flat->set_index_params(
1744	          MakeDefaultVectorIndexParams(vector_index_params->metric_type()));
1745	
1746	      std::string index_file_path = FileHelper::MakeVectorIndexPath(
1747	          path_, column, segment_meta_->id(), block_id);
