1756	                                                 *field_with_flat, concurrency);
1757	      if (!vector_indexer.has_value()) {
1758	        return vector_indexer.error();
1759	      }
1760	
1761	      vector_indexers->insert({column, vector_indexer.value()});
1762	
1763	      new_segment_meta->remove_vector_persisted_block(column, false);
1764	      BlockMeta block;
